mapper.select:
/* AppReq06Mapper.selectMyReqPage */ SELECT U.reqId AS reqId , U.reqType AS reqType , U.reqStatus AS reqStatus , U.workYmd AS workYmd , U.startDate AS startDate , U.startTime AS startTime , U.endDate AS endDate , U.endTime AS endTime , U.leaveType AS leaveType , U.leaveDays AS leaveDays , U.schCd AS schCd , U.processComment AS processComment , U.processDate AS processDate , U.insertDate AS insertDate FROM
ORDER BY U.insertDate DESC, U.reqId DESC
ORDER BY ABS(DATEDIFF(STR_TO_DATE(COALESCE(U.workYmd,'99991231'),'%Y%m%d'), CURDATE())) ASC , U.insertDate DESC , U.reqId DESC
ORDER BY (CASE U.reqStatus WHEN '01' THEN 0 ELSE 1 END) ASC , U.insertDate DESC , U.reqId DESC
LIMIT #{limit} OFFSET #{offset}
